shellCommands.command:
curl -s -o /dev/null -w "vite:%{http_code}\n" http://127.0.0.1:5181/; tail -3 /tmp/vite.log; cd /tmp/pwcheck && export LD_LIBRARY_PATH=$(find /tmp/libs -name "*.so*" -printf '%h\n' | sort -u | paste -sd:) && cat > smoke.mjs <<'EOF'
import {chromium} from 'playwright';
const b = await chromium.launch({args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu']});
const p = await b.newPage();
await p.goto('about:blank');
console.log('blank ok', await p.evaluate(() => 1+1));
await p.goto('http://127.0.0.1:5181/', {waitUntil: 'load', timeout: 30000});
console.log('title', await p.title());
await b.close();
EOF
timeout 120 node smoke.mjs 2>&1 | grep -v "^\s*-" | head -20

cd /tmp/pwcheck && export LD_LIBRARY_PATH=$(find /tmp/libs -name "*.so*" -printf '%h\n' | sort -u | paste -sd:) && cat > smoke2.mjs <<'EOF'
import {chromium} from 'playwright';
const b = await chromium.launch({args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu']});
b.on('disconnected', () => console.log('BROWSER DISCONNECTED'));
const p = await b.newPage();
p.on('crash', () => console.log('PAGE CRASH'));
p.on('console', (m) => console.log('console:', m.type(), m.text().slice(0, 200)));
p.on('pageerror', (e) => console.log('pageerror:', e.message.slice(0, 300)));
await p.setContent('<html><body><canvas id=c width=100 height=50></canvas><script>document.getElementById("c").getContext("2d").fillRect(0,0,5,5);console.log("canvas ok")</script></body></html>');
console.log('static canvas page ok');
await p.goto('http://127.0.0.1:5181/?probe=1', {waitUntil: 'commit', timeout: 30000}).catch(e => console.log('goto err', e.message.split('\n')[0]));
await new Promise(r => setTimeout(r, 8000));
console.log('after wait, url:', p.url());
try { console.log('root html len', (await p.content()).length); } catch (e) { console.log('content err', e.message.split('\n')[0]); }
await b.close();
EOF
timeout 120 node smoke2.mjs 2>&1 | head -30

cd /tmp/pwcheck && export LD_LIBRARY_PATH=$(find /tmp/libs -name "*.so*" -printf '%h\n' | sort -u | paste -sd:) && cat > isolate.mjs <<'EOF'
import {chromium} from 'playwright';
const mode = process.argv[2];
const b = await chromium.launch({args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu']});
b.on('disconnected', () => console.log(mode, 'BROWSER DISCONNECTED'));
const p = await b.newPage();
p.on('pageerror', (e) => console.log(mode, 'pageerror:', e.message.slice(0, 300)));
if (mode === 'stub') {
  await p.route('**/src/monitoring/CpuUsageChart.tsx*', (route) =>
    route.fulfill({contentType: 'application/javascript', body: 'export function CpuUsageChart(){ return null; }'}));
}
await p.goto('http://127.0.0.1:5181/', {waitUntil: 'load', timeout: 30000}).catch((e) => console.log(mode, 'goto err', e.message.split('\n')[0]));
await new Promise((r) => setTimeout(r, 8000));
try {
  console.log(mode, 'h1 =', await p.locator('h1').first().textContent({timeout: 3000}));
} catch (e) { console.log(mode, 'h1 err', e.message.split('\n')[0]); }
await b.close().catch(() => {});
EOF
timeout 100 node isolate.mjs stub 2>&1 | head -8; echo ======; timeout 100 node isolate.mjs full 2>&1 | head -8

cd /tmp/pwcheck && export LD_LIBRARY_PATH=$(find /tmp/libs -name "*.so*" -printf '%h\n' | sort -u | paste -sd:) && cat > bisect.mjs <<'EOF'
import {chromium} from 'playwright';
const mode = process.argv[2];
const b = await chromium.launch({args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu']});
b.on('disconnected', () => console.log(mode, 'BROWSER DISCONNECTED'));
const p = await b.newPage();
p.on('pageerror', (e) => console.log(mode, 'pageerror:', e.message.slice(0, 200)));
if (mode === 'plain') {
  await p.route('http://127.0.0.1:5181/', (r) => r.fulfill({contentType: 'text/html', body: '<html><body><h1>hi</h1></body></html>'}));
} else if (mode === 'noapp') {
  await p.route('**/src/App.tsx*', (r) => r.fulfill({contentType: 'application/javascript', body: 'export function App(){ return null; }'}));
} else if (mode === 'nocss') {
  await p.route('**/@fs/**', (r) => r.fulfill({contentType: 'text/plain', body: ''}));
}
await p.goto('http://127.0.0.1:5181/', {waitUntil: 'load', timeout: 30000}).catch((e) => console.log(mode, 'goto err', e.message.split('\n')[0]));
await new Promise((r) => setTimeout(r, 5000));
console.log(mode, 'alive:', await p.evaluate(() => document.body.innerText.slice(0, 40)).catch((e) => 'ERR ' + e.message.split('\n')[0]));
await b.close().catch(() => {});
EOF
for m in plain noapp; do timeout 100 node bisect.mjs $m 2>&1 | head -4; echo ===; done

mkdir -p /tmp/static && echo '<html><body><h1>hi</h1></body></html>' > /tmp/static/index.html && cd /tmp/static && (python3 -m http.server 8766 --bind 127.0.0.1 >/tmp/static.log 2>&1 &) ; sleep 2; cd /tmp/pwcheck && export LD_LIBRARY_PATH=$(find /tmp/libs -name "*.so*" -printf '%h\n' | sort -u | paste -sd:) && cat > plainhttp.mjs <<'EOF'
import {chromium} from 'playwright';
const b = await chromium.launch({args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu']});
b.on('disconnected', () => console.log('BROWSER DISCONNECTED'));
const p = await b.newPage();
await p.goto(process.argv[2], {waitUntil: 'load', timeout: 30000}).catch((e) => console.log('goto err', e.message.split('\n')[0]));
await new Promise((r) => setTimeout(r, 3000));
console.log('alive:', await p.evaluate(() => document.body.innerText).catch((e) => 'ERR ' + e.message.split('\n')[0]));
await b.close().catch(() => {});
EOF
timeout 100 node plainhttp.mjs http://127.0.0.1:8766/ 2>&1 | head -4

cat > /tmp/static/serve.mjs <<'EOF'
import {createServer} from 'node:http';
createServer((req, res) => { res.setHeader('content-type', 'text/html'); res.end('<html><body><h1>hi</h1></body></html>'); }).listen(8766, '127.0.0.1');
EOF
(node /tmp/static/serve.mjs > /tmp/static.log 2>&1 &); sleep 1; curl -s http://127.0.0.1:8766/; echo; cd /tmp/pwcheck && export LD_LIBRARY_PATH=$(find /tmp/libs -name "*.so*" -printf '%h\n' | sort -u | paste -sd:) && timeout 100 node plainhttp.mjs http://127.0.0.1:8766/ 2>&1 | head -4

